signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "showTab": {
      "type": "string",
      "description": "Set when the user asks to see the dates on one tab of the Manual In and Out screen - e.g. 'what are the dates in the pending tab'. Pass the tab name as the user says it: Regularize, Pending, Valid Swipes or Off Shifts. No date is needed (the team and admin tools still need the employee). Returns only that tab's dates and submits nothing - show the dates as returned."
    },
    "listSubordinates": {
      "type": "boolean",
      "description": "Set to true when the user asks to see the team members (subordinates) they can submit manual In and Out for - e.g. \"display all the subordinates I can apply manual In and Out for\". No employee or date is needed; the tool returns the list (number and name) and submits nothing. Show the list, then ask which one and the date."
    },
    "employeeNumber": {
      "type": "string",
      "description": "The team member's employee number, e.g. 000017. Leading zeros are optional. Either employeeNumber or employeeName must be given - ask the user which team member if neither is known."
    },
    "employeeName": {
      "type": "string",
      "description": "The team member's name, full or partial. Either employeeNumber or employeeName must be given. If it matches more than one person the tool returns candidates - ask the user which one, never pick."
    },
    "date": {
      "type": "string",
      "description": "The off shift day (rest day / off day) of the manual In and Out, in the format returned by the dateFormat tool (MM/DD/YYYY for en-US, otherwise DD/MM/YYYY). Ask the user for it, then call the tool straight away with the employee and the date alone - the tool checks which tab the day is on and returns the shift details before anything else is asked. Also call with the date when the user asks for the status of a pending request on that date - for a Pending day the tool returns the status, what was requested (old -> new In/Out and break times), the comment and who it is waiting for (pendingRequest); show that as returned."
    },
    "inDate": {
      "type": "string",
      "description": "In date, in the format returned by the dateFormat tool. Give it with inTime when the user is giving the In. The screen submits an In on its own, an Out on its own, or both, so one side is enough - ask the user which they want to give and never insist on the other. Offer suggested.inDate as the default; never assume it."
    },
    "inTime": {
      "type": "string",
      "description": "In time in HH:mm 24-hour format, e.g. 08:30. Give it with inDate when the user is giving the In; leave both out for an Out-only entry. Offer suggested.inTime as the default."
    },
    "outDate": {
      "type": "string",
      "description": "Out date, in the format returned by the dateFormat tool. Give it with outTime when the user is giving the Out; leave both out for an In-only entry. An Out Date on the day AFTER the In Date is normal for shifts past midnight (shiftDetails.canEndNextDay) - never question it. Offer suggested.outDate as the default."
    },
    "outTime": {
      "type": "string",
      "description": "Out time in HH:mm 24-hour format, e.g. 17:30. Give it with outDate when the user is giving the Out. Check it against outDate, not against inTime. Offer suggested.outTime as the default."
    },
    "reason": {
      "type": "string",
      "description": "Reason/comment explaining why the off shift manual In and Out is being submitted. Required before the record is submitted."
    },
    "breaks": {
      "type": "array",
      "description": "Optional breaks - none, one or as many as the user wants. After showing the shift details, tell the user they can add breaks, but do not insist. Each break needs both times and must sit within the In and Out date-times and the day's allowed period (shiftDetails.recordedBreaks lists the ones already recorded). A break after midnight is fine on a shift whose period reaches there.",
      "items": {
        "type": "object",
        "properties": {
          "breakInTime": {
            "type": "string",
            "description": "Break start time in HH:mm 24-hour format, e.g. 12:00."
          },
          "breakOutTime": {
            "type": "string",
            "description": "Break end time in HH:mm 24-hour format, e.g. 13:00."
          },
          "breakNo": {
            "type": "integer",
            "description": "Only to CHANGE a recorded break: its breakNo from shiftDetails.recordedBreaks. Leave it out to add a new break."
          }
        },
        "required": [
          "breakInTime",
          "breakOutTime"
        ]
      }
    },
    "breakInTime": {
      "type": "string",
      "description": "Single-break shorthand: break start time in HH:mm. Prefer the breaks list. If given, breakOutTime must be given too."
    },
    "breakOutTime": {
      "type": "string",
      "description": "Single-break shorthand: break end time in HH:mm. Prefer the breaks list. If given, breakInTime must be given too."
    },
    "otherEntries": {
      "type": "array",
      "description": "When the user asks for several days in one request, pass on every call the OTHER days of that request that are not submitted yet, each with the values the user gave. The screen submits such days together and refuses all of them when two overlap across midnight, so the tool checks the overlap in each day's preview. Preview every day first; submit none until all previews passed.",
      "items": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string",
            "description": "That day, in the dateFormat format."
          },
          "inDate": {
            "type": "string"
          },
          "inTime": {
            "type": "string",
            "description": "HH:mm"
          },
          "outDate": {
            "type": "string"
          },
          "outTime": {
            "type": "string",
            "description": "HH:mm"
          }
        }
      }
    },
    "confirmed": {
      "type": "boolean",
      "description": "Set to true, together with previewToken, only after the user has reviewed the preview (it names the team member) and explicitly confirmed. Set to false (or omit) to preview/validate without submitting anything. Never send it on the first call - the tool validates and returns the preview first."
    },
    "previewToken": {
      "type": "string",
      "description": "The previewToken from the preview the user confirmed. Required with confirmed:true. Without it, or if any value changed since that preview, nothing is submitted and the preview is returned again - show it and ask for confirmation."
    },
    "isGroupByEmployee": {
      "type": "boolean",
      "description": "Optional Group By Employee checkbox on the Search Criteria panel. Omit it to use the screen's own default."
    },
    "rosterGroup": {
      "type": "string",
      "description": "Optional roster group, by id or name. Omit it to use the screen's first roster group. Do not ask the user for it unless they want a specific roster."
    },
    "rosterCode": {
      "type": "string",
      "description": "Optional roster code. Takes precedence over rosterName. Omit it to use the first roster of the roster group, as the screen does."
    },
    "rosterName": {
      "type": "string",
      "description": "Optional roster name. Resolved to a roster code within the roster group. Ignored when rosterCode is given."
    }
  },
  "required": []
}
